test('native Arrange manuscript uses shared reading and heading roles without changing template artwork',async()=>{
 const f=fixture();try{await tick();const d=f.w.document,doc=d.querySelector('.ma-document'),body=doc.querySelector('.ma-block p');assert.ok(body,'the native renderer presents manuscript prose');
 const style=d.createElement('style');style.textContent=fs.readFileSync(new URL('../public/document-study/magazine-arrange.css',import.meta.url),'utf8');d.head.append(style);
 const rules=[...style.sheet.cssRules].filter(rule=>rule.selectorText&&/\.ma-(?:document|block)/.test(rule.selectorText)),matching=el=>rules.filter(rule=>el.matches(rule.selectorText));
 const reading=matching(doc).find(rule=>rule.style.getPropertyValue('font-size').includes('--t-reading'));assert.ok(reading,'manuscript size follows the shared A−/A+ reading token');assert.match(reading.style.getPropertyValue('font-family'),/--ar-ui/);assert.match(reading.style.getPropertyValue('line-height'),/--lh-read/);assert.match(reading.style.getPropertyValue('max-width'),/--measure/);
 const block=body.closest('.ma-block');block.insertAdjacentHTML('beforeend',f.w.studyReadableMarkdown.render('# Invented title\n\n## Invented heading\n\n> A written quotation, not attributed speech.'));
 assert.ok(matching(block.querySelector('h1')).some(rule=>rule.style.getPropertyValue('font-size').includes('--t-title')));assert.ok(matching(block.querySelector('h2')).some(rule=>rule.style.getPropertyValue('font-size').includes('--t-head')&&rule.style.getPropertyValue('font-weight')==='600'));
 for(const el of [doc,body,block.querySelector('h1'),block.querySelector('h2'),block.querySelector('blockquote')])assert.equal(matching(el).some(rule=>/shared-prose|Cormorant|Lora/.test(rule.style.getPropertyValue('font-family'))),false,'native text must not receive the superseded broad serif role');
 for(const media of [...style.sheet.cssRules].filter(rule=>rule.media))for(const rule of [...media.cssRules])if(rule.selectorText?.includes('.ma-document')&&doc.matches(rule.selectorText))assert.equal(rule.style.getPropertyValue('font-size'),'','phone rules must keep the shared reading scale');
 const template=d.createElement('section');template.className='c3-template';template.innerHTML='<h1>Platform artwork</h1>';d.querySelector('#workspace').append(template);assert.equal(matching(template.firstElementChild).length,0,'Arrange typography must not restyle the independent platform template owner');
 }finally{close(f);}
});

