test('article credits distinguish explicit empty wording and original publication credits without changing the source record',async()=>{const f=fixture({creditsSupport:true});try{await tick();let root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-credits]');assert.ok(panel);assert.match(root.querySelector('.ma-article-credits').textContent,/Original publication credit/);const input=panel.querySelector('[data-ma-credits-edit]');input.value='Invented photographer\nInvented translation credit';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));panel.querySelector('[data-ma-credits-save]').click();await tick();assert.deepEqual(JSON.parse(JSON.stringify(f.calls.find(c=>c.action==='credits').input.credits)),['Invented photographer','Invented translation credit']);assert.deepEqual(f.media.annotations.publicationCredits,['Original publication credit']);}finally{close(f);}});

test('saved captions render as visible words and retain focus, replacement and move controls',async()=>{const f=fixture({single:true,annotationSupport:true,replaceSupport:true,defer:true});const annotation={caption:'A visible 100% caption 瓷',credit:'Invented author'},row=f.working.projection[0],old=row.raw;row.raw+='\n%%ar-create-photo: '+JSON.stringify(annotation).replaceAll('%','\\u0025')+'%%';row.blockHash=sha(row.raw);f.working.document.text=f.working.document.text.replace(old,row.raw);const hash=sha(f.working.document.text);f.working.document.hash=f.proof.draftHash=f.proof.expected.workflow.draft=f.media.ownerRef.hash=hash;for(const p of f.working.projection){p.origin.fileHash=hash;if(p!==row)p.origin.offset+=row.raw.length-old.length;}for(const p of f.media.sources[0].placements){p.hash=hash;p.nativeOrigin.fileHash=hash;p.nativeOrigin.blockHash=row.blockHash;p.nativeOrigin.chunkEnd+=row.raw.length-old.length;p.annotation=annotation;}try{f.start();await tick();const root=f.w.document.querySelector('#magazine-arrange');assert.equal(root.querySelector('.ma-caption>span').textContent,annotation.caption);assert.equal(root.querySelector('.ma-caption>small').textContent,annotation.credit);assert.ok(root.querySelector('[data-ma-focus-x]'));assert.ok(root.querySelector('[data-ma-aspect]'));assert.ok(root.querySelector('[data-ma-change-photo]'));assert.ok(root.querySelector('[data-ma-select]'));assert.doesNotMatch(root.textContent,/ar-create-photo|same.png/);}finally{close(f);}});
test('caption and credit inputs reject stale, dirty, unsupported and invalid changes without losing entered wording',async()=>{for(const mode of ['stale','dirty','unsupported','invalid']){const f=fixture({single:true,annotationSupport:mode!=='unsupported'});try{await tick();const root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-annotation]');if(mode==='unsupported'){assert.equal(panel,null);continue;}const input=panel.querySelector('[data-ma-caption-edit]');input.value=mode==='invalid'?' outer spaces ':'Exact unsaved caption';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));if(mode==='dirty')f.proof.dirty=true;if(mode==='stale')f.proof.sequence++;panel.querySelector('[data-ma-annotation-save]').dispatchEvent(new f.w.Event('click',{bubbles:true}));await tick();assert.equal(f.calls.some(c=>c.action==='annotation'),false,mode);assert.equal(input.value,mode==='invalid'?' outer spaces ':'Exact unsaved caption');}finally{close(f);}}});
test('article empty credits and original credits are explicit distinct owner operations',async()=>{for(const original of [false,true]){const f=fixture({creditsSupport:true,defer:true});f.media.annotations.credits=['Working credit'];try{f.start();await tick();const root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-credits]'),input=panel.querySelector('textarea');if(original)panel.querySelector('[data-ma-credits-original]').click();else{input.value='';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));panel.querySelector('[data-ma-credits-save]').click();}await tick();assert.deepEqual(JSON.parse(JSON.stringify(f.calls.find(c=>c.action==='credits').input.credits)),original?null:[]);assert.deepEqual(f.media.annotations.publicationCredits,['Original publication credit']);}finally{close(f);}}});
test('large Unicode wording stays in its field with a friendly size refusal before planning',async()=>{const f=fixture({single:true,annotationSupport:true,creditsSupport:true});try{await tick();const root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-annotation]'),input=panel.querySelector('[data-ma-caption-edit]');input.value='瓷'.repeat(4000);input.dispatchEvent(new f.w.Event('input',{bubbles:true}));assert.equal(input.value.length,4000);assert.equal(panel.querySelector('[data-ma-annotation-save]').disabled,true);assert.match(panel.querySelector('[role=alert]').textContent,/too long.*kept/);assert.equal(root.querySelector('[data-ma-credits-edit]').disabled,true);assert.equal(f.calls.some(c=>c.action==='annotation'),false);}finally{close(f);}});
test('unfinished caption and credits restore after reload as local words, without automatic article save',async()=>{for(const credits of [false,true]){const first=fixture({single:true,annotationSupport:true,creditsSupport:true});let retained;try{await tick();const panel=first.w.document.querySelector(credits?'[data-ma-credits]':'[data-ma-annotation]'),input=panel.querySelector(credits?'textarea':'[data-ma-caption-edit]');input.value=credits?'Unfinished first credit\nUnfinished second credit':'Unfinished caption with 100% 瓷';input.dispatchEvent(new first.w.Event('input',{bubbles:true}));retained=first.wordingBuffer();assert.equal(first.calls.some(c=>['annotation','credits'].includes(c.action)),false);assert.ok(retained.token);}finally{close(first);}const restored=fixture({single:true,annotationSupport:true,creditsSupport:true,retainedWording:retained});try{await tick();const root=restored.w.document.querySelector('#magazine-arrange'),panel=root.querySelector(credits?'[data-ma-credits]':'[data-ma-annotation]'),input=panel.querySelector(credits?'textarea':'[data-ma-caption-edit]');assert.equal(input.value,credits?retained.values.text:retained.values.caption);assert.equal(panel.open,true);assert.match(restored.w.document.querySelector('#c3-surface-bar').textContent,/Kept on this device.*not saved/);assert.equal(restored.calls.some(c=>['annotation','credits'].includes(c.action)),false);panel.querySelector(credits?'[data-ma-credits-save]':'[data-ma-annotation-save]').click();await tick();assert.equal(restored.calls.filter(c=>['annotation','credits'].includes(c.action)).length,1);assert.equal(restored.wordingBuffer(),null);}finally{close(restored);}}});
test('changed photo or article recovery stays separate and requires an explicit discard before editing a new position',async()=>{for(const change of ['hash','placement']){const f=fixture({single:true,annotationSupport:true,defer:true}),retained={kind:'photo-annotation',token:'earlier',expectedHash:f.proof.draftHash,sequence:0,artifactId:f.media.ownerRef.artifactId,revision:f.media.revision,placementId:f.media.sources[0].placements[0].placementId,blockId:f.id,blockHash:f.working.projection[0].blockHash,values:{caption:'Exact earlier unfinished caption',credit:'Earlier credit'}};if(change==='hash')retained.expectedHash='f'.repeat(64);else retained.placementId='e'.repeat(64);let value=retained;f.w.studyDraft.getMagazineWordingDraft=()=>value;f.w.studyDraft.clearMagazineWordingDraft=()=>{value=null;};try{f.start();await tick();const root=f.w.document.querySelector('#magazine-arrange');assert.ok(root.querySelector('.ma-wording-recovery'));assert.equal(root.querySelector('[data-ma-caption-edit]'),null);assert.equal(root.querySelector('.ma-wording-recovery textarea').value,retained.values.caption);assert.equal(f.calls.some(c=>c.action==='annotation'),false);root.querySelector('[data-ma-wording-discard]').click();assert.equal(root.querySelector('.ma-wording-recovery'),null);assert.ok(root.querySelector('[data-ma-caption-edit]'));}finally{close(f);}}});
test('failed browser recovery keeps the actual field words visible and warns without claiming a local save',async()=>{const f=fixture({single:true,annotationSupport:true});try{await tick();f.w.studyDraft.retainMagazineWordingDraft=()=>{throw Error('Quota unavailable');};const root=f.w.document.querySelector('#magazine-arrange'),input=root.querySelector('[data-ma-caption-edit]');input.value='Keep these words in this window';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));assert.equal(input.value,'Keep these words in this window');assert.match(root.querySelector('[data-ma-annotation-error]').textContent,/Keep this window open/);assert.doesNotMatch(f.w.document.querySelector('#c3-surface-bar').textContent,/Kept on this device/);assert.equal(f.calls.some(c=>c.action==='annotation'),false);}finally{close(f);}});
test('unfinished invalid wording restores exactly for repair with Save disabled',async()=>{const f=fixture({single:true,annotationSupport:true,defer:true});const buffer={kind:'photo-annotation',token:'retained',expectedHash:f.proof.draftHash,sequence:0,artifactId:f.media.ownerRef.artifactId,revision:f.media.revision,placementId:f.media.sources[0].placements[0].placementId,blockId:f.id,blockHash:f.working.projection[0].blockHash,values:{caption:'  Keep outer spaces until I finish  ',credit:''}};f.w.studyDraft.getMagazineWordingDraft=()=>buffer;try{f.start();await tick();const panel=f.w.document.querySelector('[data-ma-annotation]');assert.equal(panel.querySelector('[data-ma-caption-edit]').value,buffer.values.caption);assert.equal(panel.querySelector('[data-ma-annotation-save]').disabled,true);assert.match(panel.querySelector('[role=alert]').textContent,/Review this unfinished wording/);assert.equal(f.calls.some(c=>c.action==='annotation'),false);}finally{close(f);}});

test('Undo of an earlier arrangement never discards unrelated retained wording',async()=>{const f=fixture({single:true,annotationSupport:true,defer:true});const retained={kind:'photo-annotation',token:'earlier',expectedHash:'f'.repeat(64),sequence:0,artifactId:f.media.ownerRef.artifactId,revision:f.media.revision,placementId:f.media.sources[0].placements[0].placementId,blockId:f.id,blockHash:f.working.projection[0].blockHash,values:{caption:'Keep this unfinished caption independently',credit:'Earlier credit'}};let value=retained;f.w.studyDraft.getMagazineWordingDraft=()=>value;f.w.studyDraft.clearMagazineWordingDraft=()=>{value=null;};const state=f.w.studyDraft.magazineArrangeState;f.w.studyDraft.magazineArrangeState=()=>({...state(),canUndo:true});try{f.start();await tick();f.w.document.querySelector('[data-ma-undo]').click();await tick();assert.ok(f.calls.some(c=>c.action==='undo'));assert.deepEqual(value,retained);assert.equal(f.w.document.querySelector('.ma-wording-recovery textarea').value,retained.values.caption);}finally{close(f);}});
test('cover and opener expose exact caption actions without gaining move or replacement controls',async()=>{for(const role of ['cover','opener']){const f=fixture({single:true,annotationSupport:true,replaceSupport:true,defer:true});const placement=f.media.sources[0].placements[0];placement.nativeOrigin.role=role;placement.structuralPath=role==='cover'?'portrait':'parts/0/opener';try{f.start();await tick();const root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-annotation]');assert.ok(panel,role);assert.equal(root.querySelector('[data-ma-select],[data-ma-change-photo],[data-ma-focus]'),null);const input=panel.querySelector('[data-ma-caption-edit]');input.value='Exact '+role+' caption';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));panel.querySelector('[data-ma-annotation-save]').click();await tick();const saved=f.calls.find(c=>c.action==='annotation');assert.equal(saved.input.placementId,placement.placementId);assert.equal(saved.input.annotation.caption,'Exact '+role+' caption');}finally{close(f);}}});

test('a top-level side occurrence exposes caption actions without structural photo controls',async()=>{const f=fixture({single:true,annotationSupport:true,replaceSupport:true,defer:true}),placement=f.media.sources[0].placements[0];placement.nativeOrigin.kind='side';placement.nativeOrigin.role='side';placement.structuralPath='opening/0/side';try{f.start();await tick();const root=f.w.document.querySelector('#magazine-arrange'),panel=root.querySelector('[data-ma-annotation]');assert.ok(panel);assert.equal(root.querySelector('[data-ma-select],[data-ma-change-photo],[data-ma-focus]'),null);const input=panel.querySelector('[data-ma-caption-edit]');input.value='Exact side caption';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));panel.querySelector('[data-ma-annotation-save]').click();await tick();const saved=f.calls.find(c=>c.action==='annotation');assert.equal(saved.input.placementId,placement.placementId);assert.equal(saved.input.annotation.caption,'Exact side caption');}finally{close(f);}});
